const CATEGORIES = CATEGORY_RAW.trim().split('\n').filter(Boolean).map((line, index) => {
  const [name, icon, note, entries] = line.split('~');
  return {
    id: `category-${index + 1}`,
    slug: name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
    name,
    icon,
    note,
    words: entries.split(';').map(entry => {
      const splitAt = entry.indexOf('=');
      return { word: entry.slice(0, splitAt).trim(), meaning: entry.slice(splitAt + 1).trim() };
    })
  };
});

const CATEGORY_REFINEMENTS = [
  ['Colors and shapes','orange','amber','a warm yellow-orange color'],
  ['Health and medicine','cold','common cold','a common illness affecting the nose and throat'],
  ['Sports equipment','gloves','goalkeeper gloves','padded hand coverings worn by a goalkeeper'],
  ['Travel essentials','backpack','carry-on bag','a small bag taken inside a plane or train']
];
CATEGORY_REFINEMENTS.forEach(([categoryName, oldWord, word, meaning]) => {
  const category = CATEGORIES.find(item => item.name === categoryName);
  const entry = category?.words.find(item => item.word === oldWord);
  if (entry) Object.assign(entry, { word, meaning });
});
